def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[+\-*/(),:=<>]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "neg": 4,
        ":": 5,
    }

    def integer(text):
        text = text.strip()
        negative = text.startswith("-")
        if text[:1] in ("-", "+"):
            text = text[1:]
        value = 0
        for i in range(0, len(text), 9):
            chunk = text[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return -value if negative else value

    def parse(formula):
        nodes = []
        operators = []
        frames = []
        pending_function = None
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                nodes.append((op, left, right))

        for token in token_pattern.findall(formula):
            if token[0].isdigit():
                nodes.append(integer(token))
                expect_operand = False
            elif token in functions:
                pending_function = token
            elif token == "(":
                operators.append("(")
                frames.append((len(nodes), pending_function))
                pending_function = None
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                base, function = frames.pop()
                if function is not None:
                    args = tuple(nodes[base:])
                    del nodes[base:]
                    nodes.append(("call", function, args))
                expect_operand = False
            elif token[0].isalpha():
                nodes.append(("ref", token))
                expect_operand = False
            else:
                op = "neg" if token == "-" and expect_operand else token
                while operators and operators[-1] != "(":
                    top = operators[-1]
                    if precedence[top] < precedence[op]:
                        break
                    if precedence[top] == precedence[op] and op == "neg":
                        break
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def argument_values(arguments):
        for argument in arguments:
            if isinstance(argument, tuple) and argument[0] == ":":
                first = argument[1][1]
                last = argument[2][1]
                c1, c2 = sorted((ord(first[0]), ord(last[0])))
                r1, r2 = sorted((int(first[1:]), int(last[1:])))
                for row in range(r1, r2 + 1):
                    for column in range(c1, c2 + 1):
                        name = chr(column) + str(row)
                        if name in cells:
                            yield ("ref", name)
            else:
                yield argument

    values = {}
    active = set()
    exhausted = object()

    for root in cells:
        if root in values:
            continue

        tasks = [("cell", root)]
        result = 0

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in values:
                    result = values[name]
                elif name in active:
                    result = "#CYCLE!"
                elif name not in cells:
                    result = 0
                else:
                    active.add(name)
                    tasks.append(("finish", name))
                    content = cells[name].strip()
                    if content.startswith("="):
                        tasks.append(("node", parse(content[1:])))
                    else:
                        result = integer(content)

            elif kind == "finish":
                name = task[1]
                values[name] = result
                active.remove(name)

            elif kind == "node":
                node = task[1]
                if isinstance(node, int):
                    result = node
                    continue

                op = node[0]
                if op == "ref":
                    tasks.append(("cell", node[1]))
                elif op == "neg":
                    tasks.append(("neg",))
                    tasks.append(("node", node[1]))
                elif op == "call":
                    function, arguments = node[1], node[2]
                    if function == "IF":
                        tasks.append(("if", arguments[1], arguments[2]))
                        tasks.append(("node", arguments[0]))
                    else:
                        iterator = argument_values(arguments)
                        tasks.append(("aggregate_next", function, iterator, None))
                else:
                    tasks.append(("binary_left", op, node[2]))
                    tasks.append(("node", node[1]))

            elif kind == "neg":
                if not isinstance(result, str):
                    result = -result

            elif kind == "binary_left":
                if not isinstance(result, str):
                    tasks.append(("binary_right", task[1], result))
                    tasks.append(("node", task[2]))

            elif kind == "binary_right":
                if isinstance(result, str):
                    continue

                op, left, right = task[1], task[2], result
                if op == "+":
                    result = left + right
                elif op == "-":
                    result = left - right
                elif op == "*":
                    result = left * right
                elif op == "/":
                    if right == 0:
                        result = "#DIV/0!"
                    else:
                        quotient = abs(left) // abs(right)
                        result = -quotient if (left < 0) != (right < 0) else quotient
                elif op == "=":
                    result = int(left == right)
                elif op == "<>":
                    result = int(left != right)
                elif op == "<":
                    result = int(left < right)
                elif op == "<=":
                    result = int(left <= right)
                elif op == ">":
                    result = int(left > right)
                elif op == ">=":
                    result = int(left >= right)

            elif kind == "if":
                if not isinstance(result, str):
                    tasks.append(("node", task[1] if result else task[2]))

            elif kind == "aggregate_next":
                function, iterator, accumulator = task[1:]
                node = next(iterator, exhausted)
                if node is exhausted:
                    result = 0 if accumulator is None else accumulator
                else:
                    tasks.append(
                        ("aggregate_add", function, iterator, accumulator)
                    )
                    tasks.append(("node", node))

            elif kind == "aggregate_add":
                if isinstance(result, str):
                    continue

                function, iterator, accumulator = task[1:]
                if accumulator is None:
                    accumulator = result
                elif function == "SUM":
                    accumulator += result
                elif function == "MIN":
                    accumulator = min(accumulator, result)
                else:
                    accumulator = max(accumulator, result)
                tasks.append(
                    ("aggregate_next", function, iterator, accumulator)
                )

    return {name: values[name] for name in cells}
